values
('bmlt-bloodbank-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',800,'{"question":"The universal red cell donor for emergency use, when group is unknown, is generally:","translation":"Emergency मा group थाहा नभए universal red cell donor कुन हो?","options":["O Rh-negative packed red cells","AB Rh-positive plasma","A Rh-positive whole blood","B Rh-negative plasma"],"correctIndex":0,"explanation":"O Rh-negative red cells lack A, B and D antigens.","explanationNe":"O Rh-negative RBC मा A, B र D antigen हुँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',801,'{"question":"The universal plasma donor ABO group is:","translation":"ABO universal plasma donor कुन group हो?","options":["AB","O","A","B"],"correctIndex":0,"explanation":"AB plasma contains neither anti-A nor anti-B.","explanationNe":"AB plasma मा anti-A र anti-B हुँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',802,'{"question":"Forward ABO grouping tests patient red cells with:","translation":"Forward ABO grouping मा patient RBC लाई केसँग test गरिन्छ?","options":["Known anti-A and anti-B reagents","Patient serum only","Anti-D only","Normal saline only"],"correctIndex":0,"explanation":"Forward grouping detects A/B antigens on red cells.","explanationNe":"Known anti-A र anti-B reagent प्रयोग गरिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',803,'{"question":"Reverse ABO grouping tests patient serum against:","translation":"Reverse grouping मा patient serum केसँग test गरिन्छ?","options":["Known A1 and B red cells","Patient red cells only","Platelets","Donor plasma only"],"correctIndex":0,"explanation":"Reverse grouping detects expected anti-A or anti-B in serum.","explanationNe":"Known A1 र B red cells सँग serum test गरिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',804,'{"question":"Group A individuals normally have which antibody in plasma?","translation":"Group A को plasma मा सामान्यतः कुन antibody हुन्छ?","options":["Anti-B","Anti-A","Anti-D always","No ABO antibody"],"correctIndex":0,"explanation":"Group A red cells express A antigen and plasma usually contains anti-B.","explanationNe":"Group A मा anti-B हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',805,'{"question":"The Rh(D) antigen is considered:","translation":"Rh(D) antigen कस्तो हुन्छ?","options":["Highly immunogenic","A naturally occurring ABO antibody","A plasma protein","An enzyme"],"correctIndex":0,"explanation":"D is a highly immunogenic red-cell antigen.","explanationNe":"D अत्यन्त immunogenic RBC antigen हो।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',806,'{"question":"A major crossmatch tests:","translation":"Major crossmatch मा के test गरिन्छ?","options":["Recipient serum/plasma against donor red cells","Donor serum against recipient urine","Recipient cells against saline only","Donor platelets against recipient serum"],"correctIndex":0,"explanation":"Major crossmatch checks recipient antibodies against donor red cells.","explanationNe":"Recipient serum/plasma लाई donor RBC सँग test गरिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',807,'{"question":"A compatible crossmatch means:","translation":"Compatible crossmatch को अर्थ के हो?","options":["No significant incompatibility detected under test conditions","All transfusion risks are absent","Donor and recipient have identical DNA","No antibody can ever develop"],"correctIndex":0,"explanation":"Compatibility testing reduces risk but cannot eliminate every transfusion risk.","explanationNe":"Test मा significant incompatibility नदेखिएको हो; सबै risk शून्य होइन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',808,'{"question":"The direct antiglobulin test detects:","translation":"DAT ले के पत्ता लगाउँछ?","options":["In-vivo coating of RBCs by IgG and/or complement","Free serum antibody only","ABO antigen in saliva","Platelet aggregation"],"correctIndex":0,"explanation":"DAT detects immunoglobulin or complement attached to red cells in the body.","explanationNe":"शरीरभित्र RBC मा लागेको IgG वा complement पत्ता लगाउँछ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',809,'{"question":"The indirect antiglobulin test is commonly used for:","translation":"IAT सामान्यतः कुन काममा प्रयोग हुन्छ?","options":["Screening serum for red-cell antibodies","Counting platelets","Measuring hemoglobin","Detecting urine glucose"],"correctIndex":0,"explanation":"IAT detects serum antibodies that react with reagent red cells.","explanationNe":"Serum मा RBC विरुद्ध antibody screening गर्न।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',810,'{"question":"The most common cause of acute severe hemolytic transfusion reaction is:","translation":"Acute severe hemolytic transfusion reaction को प्रमुख कारण के हो?","options":["ABO incompatibility","Low donor platelet count","Mild allergic reaction","Cold storage of plasma"],"correctIndex":0,"explanation":"ABO-incompatible transfusion can cause rapid intravascular hemolysis.","explanationNe":"ABO incompatibility ले तीव्र intravascular hemolysis गराउन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',811,'{"question":"If a transfusion reaction is suspected, the first action is to:","translation":"Transfusion reaction शंका भए पहिलो कदम के हो?","options":["Stop transfusion and assess the patient","Increase transfusion rate","Discard all records","Give the next unit immediately"],"correctIndex":0,"explanation":"Stop the transfusion immediately and follow the reaction protocol.","explanationNe":"Transfusion रोक्ने र patient assess गरी protocol पालना गर्ने।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',812,'{"question":"Febrile non-hemolytic transfusion reaction commonly presents with:","translation":"Febrile non-hemolytic reaction मा के देखिन सक्छ?","options":["Fever and chills","Only jaundice weeks later","Severe hypertension always","No symptoms"],"correctIndex":0,"explanation":"Fever and chills may occur without hemolysis.","explanationNe":"Hemolysis बिना fever र chills हुन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',813,'{"question":"An allergic transfusion reaction commonly presents with:","translation":"Allergic transfusion reaction को सामान्य लक्षण के हो?","options":["Urticaria or itching","Dark urine always","Severe bleeding only","Low calcium only"],"correctIndex":0,"explanation":"Mild allergic reactions often cause itching and hives.","explanationNe":"Itching र urticaria देखिन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',814,'{"question":"Packed red blood cells are primarily used to improve:","translation":"Packed RBC को मुख्य उपयोग के हो?","options":["Oxygen-carrying capacity","Platelet function","Clotting factor concentration only","Albumin level"],"correctIndex":0,"explanation":"RBC components improve oxygen delivery in appropriate patients.","explanationNe":"Oxygen-carrying capacity बढाउन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',815,'{"question":"Platelet components are used mainly for:","translation":"Platelet component मुख्यतः किन दिइन्छ?","options":["Thrombocytopenia or platelet dysfunction with bleeding risk","Isolated low albumin","Iron deficiency alone","High INR without bleeding in all cases"],"correctIndex":0,"explanation":"Platelets support primary hemostasis when indicated.","explanationNe":"Thrombocytopenia वा platelet dysfunction मा bleeding risk घटाउन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',816,'{"question":"Fresh frozen plasma contains:","translation":"Fresh frozen plasma मा के हुन्छ?","options":["Multiple coagulation factors","Only red cells","Only platelets","No proteins"],"correctIndex":0,"explanation":"Plasma provides multiple coagulation factors and other plasma proteins.","explanationNe":"धेरै coagulation factor र plasma protein हुन्छन्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',817,'{"question":"Cryoprecipitate is rich in:","translation":"Cryoprecipitate मा कुन पदार्थ धेरै हुन्छ?","options":["Fibrinogen","Hemoglobin","Sodium only","Red-cell antigen"],"correctIndex":0,"explanation":"Cryoprecipitate contains concentrated fibrinogen and selected proteins.","explanationNe":"Fibrinogen धेरै हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',818,'{"question":"Whole blood donation eligibility should be determined by:","translation":"Whole blood donation eligibility कसरी निर्धारण हुन्छ?","options":["Donor assessment and approved criteria","Donor''s blood group alone","A verbal request only","A single random test"],"correctIndex":0,"explanation":"Donor safety requires screening and eligibility assessment.","explanationNe":"Donor assessment र approved criteria अनुसार।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',819,'{"question":"Blood donations are screened for transfusion-transmissible infections according to:","translation":"Blood donation मा infection screening के अनुसार हुन्छ?","options":["National regulations and blood service policy","Donor preference only","Blood group only","Visual appearance"],"correctIndex":0,"explanation":"Required infection screening follows current regulations and service policy.","explanationNe":"National regulation र blood service policy अनुसार।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',820,'{"question":"Blood components should be stored at:","translation":"Blood component कसरी store गर्नुपर्छ?","options":["Component-specific validated conditions","Room temperature all components","One temperature for every component","Any refrigerator"],"correctIndex":0,"explanation":"Each component has defined storage temperature and time requirements.","explanationNe":"हरेक component को निर्धारित temperature र समय अनुसार।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',821,'{"question":"A blood unit label should provide:","translation":"Blood unit label मा के हुनुपर्छ?","options":["Unique donation identification and component details","Only donor first name","Only collection date","No traceability number"],"correctIndex":0,"explanation":"Traceable labels connect donation, component and testing records.","explanationNe":"Unique donation ID र component विवरण हुनुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',822,'{"question":"A clerical check before transfusion is important to:","translation":"Transfusion अघि clerical check किन आवश्यक छ?","options":["Match patient, sample and blood component identity","Determine donor occupation","Replace compatibility testing","Confirm patient diet"],"correctIndex":0,"explanation":"Bedside identity checks prevent wrong-patient transfusion errors.","explanationNe":"Wrong patient वा wrong unit transfusion रोक्न।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',823,'{"question":"A blood component with a broken or leaking bag should generally be:","translation":"Bag फुटेको वा leak भएको component के गर्ने?","options":["Quarantined and assessed; not transfused unless approved","Transfused quickly","Re-labelled as normal","Mixed with another unit"],"correctIndex":0,"explanation":"Compromised bags may be contaminated or unsafe.","explanationNe":"Quarantine गरी assess गर्ने; अनुमति नभएसम्म transfuse नगर्ने।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',824,'{"question":"The purpose of blood component separation is to:","translation":"Blood component separation किन गरिन्छ?","options":["Provide specific components according to clinical need","Make all units identical","Remove all antibodies from blood","Avoid donor testing"],"correctIndex":0,"explanation":"Component therapy allows targeted use of red cells, platelets or plasma.","explanationNe":"Clinical need अनुसार specific component दिन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-001','BMLT','BMLT NHPC Licensing','mock','free',900,'{"question":"A patient is group B. Which ABO antibody is expected in their plasma?","translation":"Group B plasma मा कुन antibody अपेक्षित हुन्छ?","options":["Anti-A","Anti-B","Anti-AB only","None"],"correctIndex":0,"explanation":"Group B red cells carry B antigen; plasma normally contains anti-A.","explanationNe":"Group B मा anti-A हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-002','BMLT','BMLT NHPC Licensing','mock','free',901,'{"question":"A patient is Rh-negative and has anti-D. Which red cells are preferred?","translation":"Rh-negative र anti-D भएको patient लाई कुन RBC प्राथमिकता दिने?","options":["Rh-negative compatible red cells","Rh-positive red cells","Any group O positive","AB positive only"],"correctIndex":0,"explanation":"Avoiding D antigen prevents antigen-antibody incompatibility.","explanationNe":"Rh-negative compatible RBC दिनुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-003','BMLT','BMLT NHPC Licensing','mock','free',902,'{"question":"A mixed-field reaction in ABO typing may occur after:","translation":"ABO typing मा mixed-field reaction कहिले देखिन सक्छ?","options":["Recent transfusion with a different ABO red-cell population","Normal saline wash only","Routine fasting","A negative urine test"],"correctIndex":0,"explanation":"Different red-cell populations can produce mixed-field agglutination.","explanationNe":"अर्को ABO population भएको recent transfusion पछि।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-004','BMLT','BMLT NHPC Licensing','mock','free',903,'{"question":"A weak or discrepant ABO result should be:","translation":"ABO discrepancy भए के गर्नुपर्छ?","options":["Investigated and resolved before routine issue","Reported by guessing","Ignored if patient is stable","Changed to group O automatically"],"correctIndex":0,"explanation":"ABO discrepancies must be resolved before assigning a definitive group.","explanationNe":"Definitive group दिनुअघि discrepancy जाँचेर समाधान गर्नुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-005','BMLT','BMLT NHPC Licensing','mock','free',904,'{"question":"Which immunoglobulin class is most commonly involved in clinically significant Rh antibodies?","translation":"Clinically significant Rh antibody प्रायः कुन class हो?","options":["IgG","IgM only","IgE","IgA only"],"correctIndex":0,"explanation":"Many Rh antibodies are IgG and can cause hemolysis or HDFN.","explanationNe":"धेरै Rh antibody IgG हुन्छन्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-006','BMLT','BMLT NHPC Licensing','mock','free',905,'{"question":"Hemolytic disease of the fetus and newborn may result from:","translation":"HDFN कसरी हुन सक्छ?","options":["Maternal IgG crossing placenta and reacting with fetal RBC antigen","Maternal IgM crossing placenta freely","Platelet antibodies only in every case","Low maternal albumin"],"correctIndex":0,"explanation":"Maternal IgG can cross the placenta and hemolyze antigen-positive fetal red cells.","explanationNe":"Maternal IgG placenta पार गरी fetal RBC antigen सँग reaction गर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-007','BMLT','BMLT NHPC Licensing','mock','free',906,'{"question":"The purpose of antibody screening before transfusion is to detect:","translation":"Transfusion अघि antibody screening किन गरिन्छ?","options":["Unexpected clinically significant red-cell antibodies","All bacterial infections","Platelet count","Hemoglobin concentration"],"correctIndex":0,"explanation":"Screening identifies antibodies that may cause incompatibility.","explanationNe":"Unexpected clinically significant RBC antibody पत्ता लगाउन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-008','BMLT','BMLT NHPC Licensing','mock','free',907,'{"question":"An antibody identification panel is used after a positive screen to:","translation":"Positive antibody screen पछि panel किन चलाइन्छ?","options":["Determine antibody specificity","Measure blood pressure","Count reticulocytes","Determine donor age"],"correctIndex":0,"explanation":"Panel cells with known antigen profiles help identify the antibody.","explanationNe":"Antibody को specificity पहिचान गर्न।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-009','BMLT','BMLT NHPC Licensing','mock','free',908,'{"question":"Electronic crossmatch may be used only when:","translation":"Electronic crossmatch कहिले प्रयोग गर्न मिल्छ?","options":["Validated system criteria and eligibility requirements are met","Any patient has no sample","There is no ABO result","The computer is offline"],"correctIndex":0,"explanation":"Electronic issue requires validated safeguards and defined eligibility.","explanationNe":"Validated system र eligibility criteria पूरा हुँदा मात्र।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-010','BMLT','BMLT NHPC Licensing','mock','free',909,'{"question":"A transfusion-associated circulatory overload is related to:","translation":"TACO कुन अवस्थासँग सम्बन्धित छ?","options":["Excessive or too rapid volume administration","RBC antigen mismatch only","Bacterial contamination only","Low platelet count"],"correctIndex":0,"explanation":"TACO is volume overload associated with transfusion.","explanationNe":"Transfusion बाट volume overload हुनु।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-011','BMLT','BMLT NHPC Licensing','mock','free',910,'{"question":"TRALI is characterized by:","translation":"TRALI को विशेषता के हो?","options":["Acute lung injury temporally associated with transfusion","Simple itching only","Chronic iron deficiency","Delayed isolated jaundice only"],"correctIndex":0,"explanation":"TRALI presents with acute respiratory compromise after transfusion.","explanationNe":"Transfusion पछि acute respiratory compromise हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-012','BMLT','BMLT NHPC Licensing','mock','free',911,'{"question":"A delayed hemolytic transfusion reaction may occur due to:","translation":"Delayed hemolytic reaction किन हुन सक्छ?","options":["An anamnestic response to a previously encountered RBC antigen","Immediate ABO error only","No antibody involvement","Platelet storage at room temperature"],"correctIndex":0,"explanation":"A previously evanescent antibody may rise after re-exposure and destroy transfused cells.","explanationNe":"पहिलेको antibody पुनः बढेर transfused RBC नष्ट गर्न सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-013','BMLT','BMLT NHPC Licensing','mock','free',912,'{"question":"A bacterial contamination reaction may present with:","translation":"Bacterial contaminated blood reaction मा के देखिन सक्छ?","options":["High fever, rigors and possible shock","Mild itching only","No symptoms in all cases","Only a low hemoglobin next month"],"correctIndex":0,"explanation":"Contaminated components can cause severe fever and sepsis-like reactions.","explanationNe":"High fever, rigor र shock हुन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-014','BMLT','BMLT NHPC Licensing','mock','free',913,'{"question":"After a suspected reaction, the blood bag and tubing should generally be:","translation":"Reaction शंका पछि bag र tubing के गर्ने?","options":["Returned to the blood bank for investigation per protocol","Discarded immediately without documentation","Reused for another patient","Stored in the patient''s room"],"correctIndex":0,"explanation":"The unit and tubing may be needed for investigation and should follow protocol.","explanationNe":"Protocol अनुसार investigation का लागि blood bank मा पठाउने।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-015','BMLT','BMLT NHPC Licensing','mock','free',914,'{"question":"Which component generally has the shortest storage life under routine conditions?","translation":"Routine condition मा सामान्यतः छोटो shelf life कुन component को हुन्छ?","options":["Platelets","Frozen plasma","Packed RBCs","Cryoprecipitate frozen"],"correctIndex":0,"explanation":"Platelets have relatively short shelf life and controlled storage requirements.","explanationNe":"Platelet को shelf life तुलनात्मक रूपमा छोटो हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-016','BMLT','BMLT NHPC Licensing','mock','free',915,'{"question":"Leukoreduced blood components are prepared to reduce:","translation":"Leukoreduced component ले के घटाउँछ?","options":["Leukocytes in the component","All red-cell antigens","All plasma proteins","Fibrinogen only"],"correctIndex":0,"explanation":"Leukoreduction lowers donor leukocyte content and certain associated risks.","explanationNe":"Component मा रहेका leukocyte घटाउँछ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-017','BMLT','BMLT NHPC Licensing','mock','free',916,'{"question":"Irradiated cellular blood components are used to prevent:","translation":"Irradiated blood component किन प्रयोग हुन्छ?","options":["Transfusion-associated graft-versus-host disease","ABO incompatibility","Iron overload","All allergic reactions"],"correctIndex":0,"explanation":"Irradiation inactivates donor T lymphocytes to prevent TA-GVHD in at-risk recipients.","explanationNe":"Donor T cell निष्क्रिय गरी TA-GVHD रोक्न।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-018','BMLT','BMLT NHPC Licensing','mock','free',917,'{"question":"Washed red cells may be indicated for patients with:","translation":"Washed RBC कुन अवस्थामा विचार गर्न सकिन्छ?","options":["Recurrent severe allergic reactions to plasma proteins in selected cases","Every anemia case","High platelet count","A positive blood group"],"correctIndex":0,"explanation":"Washing reduces residual plasma proteins in selected patients.","explanationNe":"केही patient मा plasma protein सम्बन्धी severe allergic reaction दोहोरिएमा।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-019','BMLT','BMLT NHPC Licensing','mock','free',918,'{"question":"Autologous blood donation means:","translation":"Autologous blood donation भन्नाले के बुझिन्छ?","options":["A person donates blood for their own future use","A donor gives blood to a relative only","Blood is taken from a different species","Blood is always discarded"],"correctIndex":0,"explanation":"Autologous donation is collected for the same individual.","explanationNe":"आफ्नै प्रयोगका लागि आफैले blood donate गर्नु।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-020','BMLT','BMLT NHPC Licensing','mock','free',919,'{"question":"A transfusion record should include:","translation":"Transfusion record मा के राख्नुपर्छ?","options":["Component identification, time, observations and staff documentation","Only the patient''s room number","Only the donor''s address","No monitoring information"],"correctIndex":0,"explanation":"Documentation supports traceability and patient safety.","explanationNe":"Component ID, समय, observation र staff documentation।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-021','BMLT','BMLT NHPC Licensing','mock','free',920,'{"question":"A blood donor with a temporary deferral should be:","translation":"Temporary deferral भएको donor लाई के गर्ने?","options":["Deferred for the specified period and counselled appropriately","Accepted regardless of criteria","Permanently rejected automatically","Allowed to donate without screening"],"correctIndex":0,"explanation":"Deferral protects donor and recipient; duration depends on criteria.","explanationNe":"निर्धारित अवधि defer गरी उचित जानकारी दिने।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-022','BMLT','BMLT NHPC Licensing','mock','free',921,'{"question":"The main purpose of donor consent is to:","translation":"Donor consent को मुख्य उद्देश्य के हो?","options":["Ensure the donor understands and voluntarily agrees","Replace donor screening","Guarantee all tests are negative","Avoid identity verification"],"correctIndex":0,"explanation":"Informed consent supports voluntary, informed donation.","explanationNe":"Donor ले बुझेर स्वेच्छाले सहमति दिएको सुनिश्चित गर्नु।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank-mock-023','BMLT','BMLT NHPC Licensing','mock','free',922,'{"question":"A blood unit is recalled when:","translation":"Blood unit recall कहिले गरिन्छ?","options":["A relevant safety concern or post-donation information requires action","The unit label is attractive","A patient asks for a different color","The refrigerator is clean"],"correctIndex":0,"explanation":"Recall procedures remove or investigate potentially unsafe components.","explanationNe":"Safety concern वा post-donation information ले action आवश्यक गर्दा।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
